{"path":"neuron_growth_ollama-ornith-9b_01.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Neural Network Growth</title>
<script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #05070f; overflow: hidden; }
canvas { display: block; margin: 0 auto; }
</style>
</head>
<body>
<canvas id="c" width="800" height="800"></canvas>
<script>
// ========== SETUP ==========
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const W = 800, H = 800, CX = W/2, CY = H/2;

// Colors
const C_BG = '#05070f', C_GLOW = '#101a3a', C_BRANCH = '#00e5ff', C_ACCENT = '#d6ff00',
      C_SYNAPSE = '#ff2bd6', C_PULSE = '#fff36a', C_UI = '#ffd400',
      C_SCAN = 'rgba(0, 229, 255, 0.08)';

// State
let neurons = [];
let branches = [];
let synapses = [];
let pulses = [];
let growing = true;
let maxBranchCount = 250;
let branchCount = 0;

// ========== NEURON CLASS ==========
class Neuron {
  constructor(x, y) { this.x = x; this.y = y; this.radius = 4; this.active = true; this.branches = []; }
}

// ========== GUI ==========
const gui = new dat.GUI();

const growthFolder = gui.addFolder('Growth');
growthFolder.add(neurons, '_growTimeout');
growthFolder.add({ speed: 1, depth: 12, split: 0.3, curvature: 0.3, length: 80 },
  'speed', 0.5, 3).name('Growth Speed');
growthFolder.add({ maxDepth: 12, splitChance: 0.3, curvature: 0.3, maxLength: 80 },
  'maxDepth', 6, 18).name('Max Depth');
growthFolder.add({ splitChance: 0.3, curvature: 0.3, maxLength: 80 },
  'splitChance', 0.05, 0.7).name('Split Chance');
growthFolder.add({ curvature: 0.3, maxLength: 80 },
  'curvature', 0.05, 0.7).name('Curvature');
growthFolder.add({ maxLength: 80 },
  'maxLength', 30, 150).name('Max Length');
growthFolder.open();

const synapseFolder = gui.addFolder('Synapses');
synapseFolder.add({ threshold: 25, glow: 15 },
  'threshold', 5, 60).name('Threshold');
synapseFolder.add({ glow: 15 },
  'glow', 5, 30).name('Glow');
synapseFolder.open();

const pulseFolder = gui.addFolder('Pulses');
pulseFolder.add({ speed: 2, freq: 0.002, brightness: 1.0 },
  'speed', 0.5, 5).name('Speed');
pulseFolder.add({ freq: 0.002, brightness: 1.0 },
  'freq', 0.0005, 0.01).name('Frequency');
pulseFolder.add({ brightness: 1.0 },
  'brightness', 0.3, 2).name('Brightness');
pulseFolder.open();

const visFolder = gui.addFolder('Visuals');
visFolder.add({ bg: C_BG, branch: C_BRANCH, accent: C_ACCENT, synapse: C_SYNAPSE, pulse: C_PULSE },
  'bg', '#05070f', '#1a1a3a').name('Background');
visFolder.add({ branch: C_BRANCH, accent: C_ACCENT, synapse: C_SYNAPSE, pulse: C_PULSE },
  'branch', '#00e5ff', '#101a3a').name('Branch');
visFolder.add({ accent: C_ACCENT, synapse: C_SYNAPSE, pulse: C_PULSE },
  'accent', '#d6ff00', '#2a2a0a').name('Accent');
visFolder.add({ synapse: C_SYNAPSE, pulse: C_PULSE },
  'synapse', '#ff2bd6', '#3a0a2a').name('Synapse');
visFolder.add({ pulse: C_PULSE },
  'pulse', '#fff36a', '#3a3a0a').name('Pulse');
visFolder.open();

const btns = {};
btns.regen = () => { neurons = []; branches = []; synapses = []; pulses = []; growing = true; branchCount = 0; };
btns.clear = () => { ctx.clearRect(0,0,W,H); };
btns.toggle = () => { growing = !growing; };
gui.add({ btns.regen, btns.clear, btns.toggle }, 'btns.regen').name('Regenerate');
gui.add({ btns.clear, btns.toggle }, 'btns.clear').name('Clear');
gui.add({ btns.toggle }, 'btns.toggle').name('Pause/Resume');

// ========== INIT ==========
function init() {
  for (let i = 0; i < 5; i++) {
    const r = 60 + Math.random() * 80;
    const a = Math.random() * Math.PI * 2;
    const x = CX + Math.cos(a) * r;
    const y = CY + Math.sin(a) * r;
    neurons.push(new Neuron(x, y));
  }
  requestAnimationFrame(loop);
}

// ========== GROWTH ==========
function grow() {
  if (!growing || branchCount >= maxBranchCount) return;
  const tips = branches.map(b => ({ x: b.x, y: b.y, n: b.neuron }));
  for (let tip of tips) {
    if (Math.random() > 0.02) continue;
    let angle = Math.random() * Math.PI * 2;
    if (tip.n.x < CX) angle += 0.3;
    if (tip.n.y < CY) angle -= 0.3;
    const bend = (Math.random() - 0.5) * 0.6;
    const len = Math.random() * 5 + 3;
    const nx = tip.x + Math.cos(angle + bend) * len;
    const ny = tip.y + Math.sin(angle + bend) * len;
    branches.push({ x: tip.x, y: tip.y, nx, ny, n: tip.n, color: Math.random() > 0.8 ? C_ACCENT : C_BRANCH });
    branchCount++;
    if (branches.length > 120) return;
  }
}

// ========== SYNAPSES ==========
function findSynapses() {
  for (let i = 0; i < branches.length - 1; i++) {
    for (let j = i + 1; j < branches.length; j++) {
      const a = branches[i], b = branches[j];
      const dx = a.nx - b.x, dy = a.ny - b.y;
      if (dx*dx + dy*dy < 400) {
        synapses.push({ x: (a.nx+b.x)/2, y: (a.ny+b.y)/2, active: true });
      }
    }
  }
}

// ========== PULSES ==========
function updatePulses() {
  if (pulses.length > 0) {
    pulses = pulses.filter(p => {
      if (Math.random() > 0.03) return true;
      const dx = p.nx - p.x;
      if (dx*dx + dy*dy < 0) {
        if (p.neuron) { p.neuron.x += dx; p.neuron.y += dy; return true; }
        return false;
      }
      p.x += dx * p.speed;
      p.y += dy * p.speed;
      return true;
    });
  }
}

// ========== RENDER ==========
function draw() {
  ctx.fillStyle = '#05070f';
  ctx.fillRect(0, 0, W, H);

  // Scanlines
  ctx.strokeStyle = C_SCAN;
  ctx.lineWidth = 1;
  for (let y = 0; y < H; y += 4) {
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
  }

  // Vignette
  const grad = ctx.createRadialGradient(CX, CY, 300, CX, CY, 400);
  grad.addColorStop(0, 'rgba(16,26,58,0)');
  grad.addColorStop(1, 'rgba(16,26,58,0.4)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // Branches
  for (let b of branches) {
    ctx.beginPath();
    ctx.moveTo(b.x, b.y);
    ctx.lineTo(b.nx, b.ny);
    ctx.strokeStyle = b.color;
    ctx.lineWidth = 1.2;
    ctx.shadowBlur = 6;
    ctx.shadowColor = b.color;
    ctx.stroke();
    ctx.shadowBlur = 0;
  }

  // Neurons
  for (let n of neurons) {
    if (!n.active) continue;
    ctx.beginPath();
    ctx.arc(n.x, n.y, n.radius, 0, Math.PI * 2);
    ctx.fillStyle = '#fff';
    ctx.shadowBlur = 10;
    ctx.shadowColor = C_BRANCH;
    ctx.fill();
    ctx.shadowBlur = 0;
  }

  // Synapses
  for (let s of synapses) {
    if (!s.active) continue;
    const t = Date.now() * 0.001;
    const r = 3 + Math.sin(t * 3) * 2;
    ctx.beginPath();
    ctx.arc(s.x, s.y, r, 0, Math.PI * 2);
    ctx.fillStyle = C_SYNAPSE;
    ctx.shadowBlur = 12;
    ctx.shadowColor = C_SYNAPSE;
    ctx.fill();
    ctx.shadowBlur = 0;
  }

  // Pulses
  for (let p of pulses) {
    if (!p.active) continue;
    const t = Date.now() * 0.001;
    const r = 2 + Math.sin(t * 4) * 1.5;
    ctx.beginPath();
    ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
    ctx.fillStyle = C_PULSE;
    ctx.shadowBlur = 8;
    ctx.shadowColor = C_PULSE;
    ctx.fill();
    ctx.shadowBlur = 0;
  }
}

// ========== LOOP ==========
let last = 0;
function loop(t) {
  const dt = t - last; last = t;
  if (growing) { grow(); findSynapses(); }
  updatePulses();
  draw();
  requestAnimationFrame(loop);
}

init();
</script>
</body>
</html>
